import React, { useState, useEffect } from "react";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import { PlusCircle, CheckCircle, Circle, Trash2, Play, StopCircle } from "lucide-react";
import styled from "styled-components";
import "./App.css";

const AppContainer = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  padding: 20px;
  background-color: #f4f4f9;
`;

const MatrixTable = styled.table`
  width: 100%;
  height: 100vh;
  border-collapse: collapse;
  background-color: #fff;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  table-layout: fixed;
`;

const MatrixColGroup = styled.colgroup`
  /* Set a thin width for the first column */
  & > col:nth-child(1) {
    width: 10%; /* Thin first column */
  }
  /* Set equal widths for the remaining columns */
  & > col:nth-child(2),
  & > col:nth-child(3),
  & > col:nth-child(4) {
    width: 30%; /* Equal width for the rest */
  }
`;

const QuadrantCell = styled.td`
  background-color: ${({ isOver }) => (isOver ? "#e0f7fa" : "#fafafa")};
  transition: background-color 0.3s ease;
  height: calc(50vh - 60px);
  overflow-y: auto;
  padding: 15px;
  border: 1px solid #ddd;
`;

// Your other styled components...

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({ 1: "", 2: "", 3: "", 4: "" });

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return;
    const newTask = {
      id: Date.now(),
      text: taskInputs[quadrant],
      quadrant,
      completed: false,
      dueDate: null,
      timer: 0,
      isRunning: false,
    };
    setTasks([...tasks, newTask]);
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const moveTask = (taskId, newQuadrant) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, quadrant: newQuadrant } : task)));
  };

  const setTaskDueDate = (taskId, dueDate) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, dueDate } : task)));
  };

  const toggleTaskCompletion = (taskId) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, completed: !task.completed } : task)));
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter((task) => task.id !== taskId));
  };

  const toggleTaskTimer = (taskId) => {
    setTasks(
      tasks.map((task) =>
        task.id === taskId ? { ...task, isRunning: !task.isRunning } : task
      )
    );
  };

  const updateTaskTimer = (taskId) => {
    setTasks(
      tasks.map((task) =>
        task.id === taskId && task.isRunning ? { ...task, timer: task.timer + 1 } : task
      )
    );
  };

  useEffect(() => {
    const interval = setInterval(() => {
      tasks.forEach((task) => {
        if (task.isRunning) {
          updateTaskTimer(task.id);
        }
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [tasks]);

  return (
    <DndProvider backend={HTML5Backend}>
      <AppContainer>
        <MatrixTable>
          <MatrixColGroup />
          <thead>
            <tr>
              <th colSpan="3" className="matrix-title">
                Eisenhower Matrix
              </th>
            </tr>
            <tr>
              <th></th>
              <th className="urgent-header">Urgent</th>
              <th className="not-urgent-header">Not Urgent</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <th className="important-header">Important</th>
              <Quadrant
                quadrant={1}
                tasks={tasks}
                addTask={addTask}
                moveTask={moveTask}
                setTaskDueDate={setTaskDueDate}
                toggleTaskCompletion={toggleTaskCompletion}
                deleteTask={deleteTask}
                toggleTaskTimer={toggleTaskTimer}
                taskInputs={taskInputs}
                setTaskInputs={setTaskInputs}
              />
              <Quadrant
                quadrant={2}
                tasks={tasks}
                addTask={addTask}
                moveTask={moveTask}
                setTaskDueDate={setTaskDueDate}
                toggleTaskCompletion={toggleTaskCompletion}
                deleteTask={deleteTask}
                toggleTaskTimer={toggleTaskTimer}
                taskInputs={taskInputs}
                setTaskInputs={setTaskInputs}
              />
            </tr>
            <tr>
              <th className="not-important-header">Not Important</th>
              <Quadrant
                quadrant={3}
                tasks={tasks}
                addTask={addTask}
                moveTask={moveTask}
                setTaskDueDate={setTaskDueDate}
                toggleTaskCompletion={toggleTaskCompletion}
                deleteTask={deleteTask}
                toggleTaskTimer={toggleTaskTimer}
                taskInputs={taskInputs}
                setTaskInputs={setTaskInputs}
              />
              <Quadrant
                quadrant={4}
                tasks={tasks}
                addTask={addTask}
                moveTask={moveTask}
                setTaskDueDate={setTaskDueDate}
                toggleTaskCompletion={toggleTaskCompletion}
                deleteTask={deleteTask}
                toggleTaskTimer={toggleTaskTimer}
                taskInputs={taskInputs}
                setTaskInputs={setTaskInputs}
              />
            </tr>
          </tbody>
        </MatrixTable>
      </AppContainer>
    </DndProvider>
  );
}

// Your other component functions...

export default App;
